INSERT INTO `areaclic` VALUES ('mdPSubescapular','Prega cutnea subescapular','ADIPOMETRO',,'{\\rtf1\\ansi\\deff0\\deftab720{\\fonttbl{\\f0\\fswiss MS Sans Serif;}{\\f1\\froman\\fcharset2 Symbol;}{\\f2\\fswiss\\fcharset1 MS Sans Serif;}{\\f3\\fswiss\\fprq2 Arial;}{\\f4\\fswiss\\fcharset1 MS Sans Serif;}}\r\n{\\colortbl\\red0\\green0\\blue0;}\r\n\\deflang1046\\pard\\plain\\f3\\fs22\\b Prega cut\\\'e2nea Subescapular\r\n\\par \\plain\\f3\\fs22 \r\n\\par Deve ser medida logo abaixo da extremidade da esc\\\'e1pula. A pele e o tecido subcut\\\'e2neo devem ser pin\\\'e7ados logo abaixo da borda da esc\\\'e1pula e a prega \\\'e9 angulada em 45\\\'ba a partir do plano horizontal,onde coloca-se o adip\\\'f4metro a 1 cm abaixo dos dedos que pin\\\'e7avam a prega e faz-se 3 leituras, utilizando-se a m\\\'e9dia das duas mais pr\\\'f3ximas, no mil\\\'edmetro mais pr\\\'f3ximo.\r\n\\par \\plain\\f4\\fs16 \r\n\\par }\r\n',5);
